{
  "name": "Lake Shore 340低温温度控制器",
  "name_en": "Lake Shore 340 Cryogenic Temperature Controller",
  "manufacturer": "Lake Shore Cryotronics",
  "description": "这是一款多传感器低温温度控制器，用于连接并读取低温传感器，在低温实验中进行温度监测与控温。",
  "description_en": "A multi-sensor cryogenic temperature controller used to connect to and read cryogenic sensors for temperature monitoring and control in low-temperature experiments.",
  "actions": [
    {
      "action_name": "auto-sensor",
      "description": "获取指定传感器通道",
      "description_en": "get the specified sensor channel"
    },
    {
      "action_name": "auto-temperature",
      "description": "获取温度读数",
      "description_en": "get temperature reading"
    }
  ],
  "tag_hints": [
    "cryogenic temperature control",
    "multi-sensor temperature monitoring",
    "temperature controller",
    "cryogenic sensor readout",
    "low-temperature experiments"
  ]
}

